+      body: "*"
+      response_body: "*"
+      additional_bindings: {}
+    };
+    option (google.api.method_signature) = 'bar';
+  }
+  rpc HelloWithoutOptions (Empty) returns (Empty) {}
+  rpc HelloWithSomeOptions (Empty) returns (Empty) {
+    option deprecated = true;
+    option (google.api.http) = {
