+      call.on('data', (report: OrcaLoadReport__Output) => {
+        if (!seenMetric) {
+          assert.strictEqual(report.eps, 123);
+          metricRecorder.deleteEpsMetric();
+          seenMetric = true;
+        } else {
+          assert.strictEqual(report.eps, 0);
+          done();
+        }
+      });
+    });
+  });
