+ * Unless required by applicable law or agreed to in writing, software
+ * distributed under the License is distributed on an "AS IS" BASIS,
+ * WITHOUT WARRANTIES OR CONDITIONS OF ANY KIND, either express or implied.
+ * See the License for the specific language governing permissions and
+ * limitations under the License.
+ *
+ */
+
+const grpc = require('@grpc/grpc-js');
+const protoLoader = require('@grpc/proto-loader');
+
+var PROTO_PATH = __dirname + '/../protos/helloworld.proto';
+
+const packageDefinition = protoLoader.loadSync(
+  PROTO_PATH,
+  {keepCase: true,
+   longs: String,
+   enums: String,
+   defaults: true,
+   oneofs: true
+  });
+var helloProto = grpc.loadPackageDefinition(packageDefinition).helloworld;
+
+const greeterImplementation = {
+  sayHello: (call, callback) => {
+    callback(null, { message: `Hello ${call.request.name}`});
+  }
+};
+
+const slowGreeterImplementation = {
+  sayHello: (call, callback) => {
+    const waitTimeMs = 100 + (Math.random() * 100)|0;
+    setTimeout(() => {
+      callback(null, { message: `Hello ${call.request.name}`});
+    }, waitTimeMs);
+  }
+}
+
+function serverBindPort(server, port) {
+  return new Promise((resolve, reject) => {
+    server.bindAsync(`0.0.0.0:${port}`, grpc.ServerCredentials.createInsecure(), (error, port) => {
+      if (error) {
+        reject(error);
+      } else {
+        resolve(port);
+      }
+    })
+  });
+}
+
+async function main() {
+  const channelzServer = new grpc.Server();
+  grpc.addAdminServicesToServer(channelzServer);
+  await serverBindPort(channelzServer, 50052);
+
+  const server1 = new grpc.Server();
+  server1.addService(helloProto.Greeter.service, greeterImplementation);
+  await serverBindPort(server1, 10001);
+
+  const server2 = new grpc.Server();
+  server2.addService(helloProto.Greeter.service, greeterImplementation);
+  await serverBindPort(server2, 10002);
+
+  const server3 = new grpc.Server();
+  server3.addService(helloProto.Greeter.service, slowGreeterImplementation);
+  await serverBindPort(server3, 10003);
+}
+
+main();", "docs_before_excerpt": "<!-- doc/compression.md @ 987735920ea4ba9ab005cf732d10fa4e889197a4 -->
# Compression

## Client side
The preferred method for configuring message compression on a client is to pass `options` when the client object is instantiated.

These two options control compression behavior:

**grpc.default_compression_algorithm** (int)

Default compression algorithm for the channel, applies to sending messages.

Possible values for this option are:
- `0` - No compression
- `1` - Compress with DEFLATE algorithm
- `2` - Compress with GZIP algorithm
- `3` - Stream compression with GZIP algorithm

**grpc.default_compression_level** (int)

Default compression level for the channel, applies to receiving messages.

Possible values for this option are:
- `0` - None
- `1` - Low level
- `2` - Medium level
- `3` - High level

### Code example
```javascript
client = new ExampleClient("example.com", credentials.createInsecure(), {'grpc.default_compression_algorithm': 2, 'grpc.default_compression_level': 2});
```

<!-- doc/environment_variables.md @ 987735920ea4ba9ab005cf732d10fa4e889197a4 -->
# grpc-js environment variables

`@grpc/grpc-js` exposes some configuration as environment variables that
can be set.

*For the legacy `grpc` library, the environment variables are documented
[in the main gRPC repository](https://github.com/grpc/grpc/blob/master/doc/environment_variables.md)*

* grpc_proxy, https_proxy, http_proxy
  The URI of the proxy to use for HTTP CONNECT support. These variables are
  checked in order, and the first one that has a value is used.

* no_grpc_proxy, no_proxy
  A comma separated list of hostnames, IP addresses,
  or CIDR blocks to connect to without using a proxy even
  if a proxy is set, for example: no_proxy=example.com,192.168.0.1,192.168.0.0/16.
  These variables are checked in order, and the first one
  that has a value is used.

* GRPC_SSL_CIPHER_SUITES
  A colon separated list of cipher suites to use with OpenSSL
  Defaults to the defaults for Node.js

* GRPC_DEFAULT_SSL_ROOTS_FILE_PATH
  PEM file to load SSL roots from

* GRPC_NODE_TRACE, GRPC_TRACE
  A comma separated list of tracers that provide additional insight into how
  grpc-js is processing requests via debug logs. Available tracers include:
  - `call_stream` - Traces client request internals
  - `channel` - Traces channel events
  - `connectivity_state` - Traces channel connectivity state changes
  - `dns_resolver` - Traces DNS resolution
  - `ip_resolver` - Traces IPv4/v6 resolution
  - `pick_first` - Traces the pick first load balancing policy
  - `proxy` - Traces proxy operations
  - `resolving_load_balancer` - Traces the resolving load balancer
  - `round_robin` - Traces the round robin load balancing policy
  - `server` - Traces high-level server events
  - `server_call` - Traces server handling of individual requests
  - `subchannel` - Traces subchannel connectivity state and errors
  - `subchannel_refcount` - Traces subchannel refcount changes. Includes per-call logs.
  - `subchannel_flowctrl` - Traces HTTP/2 flow control. Includes per-call logs.
  - `subchannel_internals` - Traces HTTP/2 session state. Includes per-call logs.
  - `channel_stacktrace` - Traces channel construction events with stack traces.
  - `keepalive` - Traces gRPC keepalive pings
  - `outlier_detection` - Traces outlier detection events

  The following tracers are added by the `@grpc/grpc-js-xds` library:
  - `cds_balancer` - Traces the CDS load balancing policy
  - `eds_balancer` - Traces the EDS load balancing policy
  - `priority` - Traces the priority load balancing policy
  - `weighted_target` - Traces the weighted target load balancing policy
  - `xds_client` - Traces the xDS Client
  - `xds_cluster_manager` - Traces the xDS cluster manager load balancing policy
  - `xds_resolver` - Traces the xDS name resolver

  'all' can additionally be used to turn all traces on.
  Individual traces can be disabled by prefixing them with '-'.

* GRPC_NODE_VERBOSITY, GRPC_VERBOSITY
  Default gRPC logging verbosity - one of:
  - DEBUG - log all gRPC messages
  - INFO - log INFO and ERROR message
  - ERROR - log only errors (default)
  - NONE - won't log any

* GRPC_NODE_USE_ALTERNATIVE_RESOLVER
  Allows changing dns resolve behavior and parse DNS server authority as described in https://github.com/grpc/grpc/blob/master/doc/naming.md
  - true - use alternative resolver
  - false - use default resolver (default)

<!-- examples/load_balancing/README.md @ 987735920ea4ba9ab005cf732d10fa4e889197a4 -->
# Load balancing

This examples shows how `Client` can pick different load balancing policies.

## Try it

```
node server.js
```

```
node client.js
```

## Explanation

Two echo servers are serving on "0.0.0.0:50051" and "0.0.0.0:50052". They will include their serving address in the response. So the server on "0.0.0.0:50051" will reply to the RPC with this is examples/load_balancing (from 0.0.0.0:50051).

Two clients are created, to connect to both of these servers. Each client picks a different load balancer (using the `grpc.service_config` option): `pick_first` or `round_robin`.

Note that balancers can also be switched using service config, which allows service owners (instead of client owners) to pick the balancer to use. Service config doc is available at https://github.com/grpc/grpc/blob/master/doc/service_config.md.

### pick_first

The first client is configured to use `pick_first`. `pick_first` tries to connect to the first address, uses it for all RPCs if it connects, or try the next address if it fails (and keep doing that until one connection is successful). Because of this, all the RPCs will be sent to the same backend. The responses received all show the same backend address.

```
this is examples/load_balancing (from 0.0.0.0:50051)
this is examples/load_balancing (from 0.0.0.0:50051)
this is examples/load_balancing (from 0.0.0.0:50051)
this is examples/load_balancing (from 0.0.0.0:50051)
this is examples/load_balancing (from 0.0.0.0:50051)
this is examples/load_balancing (from 0.0.0.0:50051)
this is examples/load_balancing (from 0.0.0.0:50051)
this is examples/load_balancing (from 0.0.0.0:50051)
this is examples/load_balancing (from 0.0.0.0:50051)
this is examples/load_balancing (from 0.0.0.0:50051)
```

### round_robin

The second client is configured to use `round_robin`. `round_robin` connects to all the addresses it sees, and sends an RPC to each backend one at a time in order. E.g. the first RPC will be sent to backend-1, the second RPC will be sent to backend-2, and the third RPC will be sent to backend-1 again.

```
this is examples/load_balancing (from 0.0.0.0:50051)
this is examples/load_balancing (from 0.0.0.0:50051)
this is examples/load_balancing (from 0.0.0.0:50052)
this is examples/load_balancing (from 0.0.0.0:50051)
this is examples/load_balancing (from 0.0.0.0:50052)
this is examples/load_balancing (from 0.0.0.0:50051)
this is examples/load_balancing (from 0.0.0.0:50052)
this is examples/load_balancing (from 0.0.0.0:50051)
this is examples/load_balancing (from 0.0.0.0:50052)
this is examples/load_balancing (from 0.0.0.0:50051)
```

Note that it's possible to see two consecutive RPC sent to the same backend. That's because `round_robin` only picks the connections ready for RPCs. So if one of the two connections is not ready for some reason, all RPCs will be sent to the ready connection.

